 public static function validate_payment_settlement($batch,$results){if(!is_array($batch)||empty($batch['external_reference'])||empty($batch['payment_method'])||empty($batch['payment_date'])||!isset($batch['expected_total']))return self::fail('payment_reference_missing','Settlement requires payment method, date, external reference and expected total.');if(!self::valid_date($batch['payment_date'])||!is_array($results)||empty($results))return self::fail('payment_results_missing','A valid date and per-beneficiary results are required.');$seen=array();$result_total=0;foreach($results as $r){if(!is_array($r)||empty($r['beneficiary_id'])||empty($r['status'])||!isset($r['amount']))return self::fail('payment_result_invalid','Every result must identify beneficiary, amount and outcome.');$id=(string)$r['beneficiary_id'];if(isset($seen[$id]))return self::fail('payment_duplicate_beneficiary','A batch cannot duplicate a beneficiary result.');$seen[$id]=true;try{$amt=self::decimal_to_minor($r['amount']);}catch(InvalidArgumentException $e){return self::fail('payment_amount_invalid','Payment amount must be a non-negative decimal.');}if($amt<0||!in_array(strtoupper((string)$r['status']),array('SETTLED','FAILED','RETURNED','PENDING'),true))return self::fail('payment_result_invalid','Payment amount or result state is invalid.');$result_total+=$amt;}try{$expected_total=self::decimal_to_minor($batch['expected_total']);}catch(InvalidArgumentException $e){return self::fail('payment_total_invalid','Expected batch total must be a non-negative decimal.');}if($expected_total!==$result_total)return self::fail('payment_total_mismatch','Beneficiary result amounts do not reconcile to the expected batch total.');return array('ok'=>true,'code'=>'ok','message'=>'Settlement evidence is structurally complete; bank reconciliation remains separate.');}
